#[cfg(test)]mod earthquake62_development_tests {
 use super::*;
 fn catalog()->SpriteActionCatalog {SpriteActionCatalog::parse_for_inspection(&[b"11297 0 0\n".as_slice(),include_bytes!(r"D:\lineage開發\3-lito開發\lito重建版\驗證紀錄\current\native-E149-earthquake62-silence64-inspection\20261024-132318-591306\1812.definition.txt"),include_bytes!(r"D:\lineage開發\3-lito開發\lito重建版\驗證紀錄\current\native-E149-earthquake62-silence64-inspection\20261024-132318-591306\1813.definition.txt"),include_bytes!(r"D:\lineage開發\3-lito開發\lito重建版\驗證紀錄\current\native-E149-earthquake62-silence64-inspection\20261024-132318-591306\1814.definition.txt")].concat(),super::super::sprite_actions::ActionLimits::default()).unwrap()}
 fn world()->World {let mut w=super::super::native_login::LoginController::default().snapshot().world.clone();let f:Value=serde_json::from_slice(include_bytes!(r"D:\lineage開發\3-lito開發\lito重建版\LiTo381-Modern\tests\fixtures\native-world-current.json")).unwrap();for key in ["world","start","status","actor","bot"]{let h=f["packets"][key].as_str().unwrap();w.accept(&(0..h.len()).step_by(2).map(|i|u8::from_str_radix(&h[i..i+2],16).unwrap()).collect::<Vec<_>>()).unwrap();}w.learned_skills.insert(62);w}
 fn packet(w:&World)->Vec<u8>{let a=w.own_actor().unwrap();let mut b=vec![0x39,18];b.extend(a.id.to_le_bytes());b.extend(a.x.to_le_bytes());b.extend(a.y.to_le_bytes());b.push(a.heading);b.extend(7_u32.to_le_bytes());b.extend(1812_u16.to_le_bytes());b.extend([0,0,0]);b.extend(2_u16.to_le_bytes());for hit in [0x20,0]{b.extend(a.id.to_le_bytes());b.push(hit);}b}
 fn event(w:&World)->EnteredEvent{let a=w.own_actor().unwrap();EnteredEvent{actor:a.id,sequence:a.action_sequence,action:18,frame:1,event:"Hit".into(),sound:None,prepared_audio:None}}
 fn model()->Effects {let mut e=Effects::default();let mut a=qualify_earthquake(&catalog()).unwrap().remove(0).2;for f in &mut a.frames{f.events.retain(|e|!matches!(e,FrameEvent::Sound(_)));}e.clips.insert(1812,Clip::new(Arc::new(a)).unwrap());e}
 #[test]fn original_definition_keeps_unrotated_frames_long_holds_and_all_three_layers(){let c=catalog();let a=qualify_earthquake(&c).unwrap().remove(0).2;assert_eq!(a.frames[0].subframe,0);assert_eq!(a.frames[15].subframe,15);assert_eq!(a.frames[12..].iter().map(|f|f.duration_ticks).collect::<Vec<_>>(),vec![48;4]);assert_eq!(a.frames[1].events,vec![FrameEvent::Sound(716)]);assert_eq!(a.frames[5].events,vec![FrameEvent::Hit]);assert!(matches!(finite_area_mix(1812),Mix::Over));let p=super::super::native_actor_layers::Plan::from_catalog(&c,1812).unwrap().bind(0).unwrap();assert_eq!(p.shadow.as_deref(),Some("1813-0.spr"));assert_eq!(p.attachments.len(),1);assert_eq!(p.attachments[0].0,"1814-0.spr");}
 #[test]fn exact_callbacks_hit_at499ms_then_keep_source_zero_dwell_until10038ms(){let clip=Clip::new(Arc::new(qualify_earthquake(&catalog()).unwrap().remove(0).2)).unwrap();let mut p=clip.start();let mut sample=p.advance(0).unwrap();let mut hits=vec![];let mut now=0;while !sample.finished {for c in &sample.crossed_cues{if c.event==FrameEvent::Hit{hits.push(now);}}now=p.next_callback_millis().unwrap();sample=p.advance(now*1_000_000).unwrap();}assert_eq!(hits,vec![499]);assert_eq!(now,10038);assert_eq!(sample.source_frame,0);let mut p=clip.start();p.advance(0).unwrap();assert_eq!(p.advance(9_000_000_000).unwrap().source_frame,2);assert_eq!(p.next_callback_millis(),Some(9125));}
 #[test]fn packet_is_type_zero_and_invalid_target_tail_is_atomic(){let mut w=world();let b=packet(&w);assert_eq!(decode(&b).unwrap().unwrap().graphics,1812);let mut wrong=b.clone();wrong[17]=8;assert!(decode(&wrong).unwrap().is_none());let mut wrong=b.clone();wrong.pop();let before=serde_json::to_value(&w).unwrap();assert!(w.accept(&wrong).is_err());assert_eq!(serde_json::to_value(&w).unwrap(),before);}
 #[test]fn centered_origin_does_not_follow_first_target_caster_motion_or_heading(){let mut w=world();let b=packet(&w);w.accept(&b).unwrap();let c=w.many_attacks.last().unwrap().clone();assert!(c.target_origin.is_none());let mut e=model();e.update(&w,[&event(&w)].into_iter(),0);let own=w.own_actor().unwrap().id;w.actors.get_mut(&own).unwrap().x+=20;w.actors.get_mut(&own).unwrap().heading=7;e.update(&w,std::iter::empty(),83_000_000);assert_eq!(e.active[0].cue.attack.position,c.attack.position);assert_eq!(e.active[0].cue.targets.len(),2);}
 #[test]fn Hit_is_diagnostic_without_guessing_relative_hurt_or_mutating_authority(){let mut w=world();w.accept(&packet(&w)).unwrap();let before=serde_json::to_value(&w).unwrap();let mut e=model();assert!(e.update(&w,[&event(&w)].into_iter(),0).is_empty());for at in [83,208,333,499]{assert!(e.update(&w,std::iter::empty(),at*1_000_000).is_empty());}assert_eq!(e.hits,1);assert_eq!(e.non_audio.len(),1);assert_eq!(e.non_audio[0]["relative_graphics_hurt_binding_pending"],true);assert_eq!(serde_json::to_value(&w).unwrap(),before);}
 #[test]fn failed_reprepare_retires_once_and_releases_active_audio_sequence(){let mut w=world();w.accept(&packet(&w)).unwrap();let mut e=model();e.update(&w,[&event(&w)].into_iter(),0);let mut restored=Effects::default();restored.restore_history(e.history());restored.error=Some("cancelled asset preparation".into());restored.update(&w,std::iter::empty(),83_000_000);assert!(restored.history().active_sequences().is_empty());let view=ViewProjection{anchor_cell:WorldCell{x:0,y:0},anchor_pixel:super::super::world_map::PixelPoint{x:0,y:0}};let mut q=vec![];restored.draw_to(&mut Target::Fragments(&mut q),view,83_000_000);assert!(q.is_empty());drop(q);assert_eq!(restored.omitted,1);restored.update(&w,[&event(&w)].into_iter(),125_000_000);assert_eq!(restored.omitted,1);}
 #[test]
 #[ignore="LITO_SHARED_RESOURCE_ROOT; original1812/1813/1814/716; memory fragments/history only"]
 fn original_bank_draws_Over_Screen_Shadow_at_wire_origin_and_freezes_after_launch(){let root:std::path::PathBuf=std::env::var_os("LITO_SHARED_RESOURCE_ROOT").expect("explicit shared root").into();let cancel=AtomicBool::new(false);let mut w=world();w.accept(&packet(&w)).unwrap();let origin=w.many_attacks.last().unwrap().attack.position;let mut e=Effects::default();e.prepare(&root,&w,&cancel);assert!(e.error.is_none());assert_eq!(e.class1_banks[&1812].bank.animation(1812,0).unwrap().frames.len(),16);assert!(e.update(&w,[&event(&w)].into_iter(),0).is_empty());let view=ViewProjection{anchor_cell:WorldCell{x:i32::from(origin[0]),y:i32::from(origin[1])},anchor_pixel:super::super::world_map::PixelPoint{x:400,y:300}};let mut q=vec![];let(receipt,audio)=e.draw_to(&mut Target::Fragments(&mut q),view,0);assert_eq!(q.len(),3);assert!(matches!((q[0].mix,q[1].mix,q[2].mix),(Mix::Over,Mix::Screen,Mix::Shadow)));assert!(q.iter().all(|p|p.position==WorldCell{x:i32::from(origin[0]),y:i32::from(origin[1])}));assert_eq!(audio.iter().filter(|a|a.actor==0&&a.sound==Some(716)&&a.prepared_audio.is_some()).count(),1);assert_eq!(receipt["effects"][0]["subframe"],1);drop(q);let h=e.history();w.actors.clear();w.many_attacks.clear();w.learned_skills.clear();let mut same=Effects::default();same.restore_history(h);same.prepare(&root,&w,&cancel);same.update(&w,std::iter::empty(),83_000_000);let mut q=vec![];let(_,audio)=same.draw_to(&mut Target::Fragments(&mut q),view,83_000_000);assert_eq!(q.len(),3);assert!(audio.is_empty());}
}
